2	import { H3, serveStatic, type ServeStaticOptions } from "../src/index.ts";
3	import { describeMatrix } from "./_setup.ts";
4	
5	describeMatrix("serve static", (t, { it, expect }) => {
6	  beforeEach(() => {
7	    const serveStaticOptions: ServeStaticOptions = {
8	      getContents: vi.fn((id) => (id.includes("404") ? undefined : `asset:${id}`)),
9	      getMeta: vi.fn((id) =>
10	        id.includes("404")
11	          ? undefined
12	          : {
13	              type: "text/plain",
14	              encoding: "utf8",
15	              etag: "w/123",
16	              mtime: 1_700_000_000_000,
17	              path: id,
18	              size: `asset:${id}`.length,
19	            },
20	      ),
21	      indexNames: ["/index.html"],
22	      encodings: { gzip: ".gz", br: ".br" },
23	      headers: {
24	        "cache-control": "public, max-age=86400",
25	      },
26	    };
27	
28	    t.app.all("/**", (event) => {
29	      return serveStatic(event, serveStaticOptions);
30	    });
31	  });
32	
33	  const expectedHeaders = {
34	    "content-type": "text/plain",
35	    etag: "w/123",
36	    "content-encoding": "utf8",
37	    "last-modified": new Date(1_700_000_000_000).toUTCString(),
38	    vary: "accept-encoding",
39	    "cache-control": "public, max-age=86400",
40	  };
41	
42	  it("Can serve asset (GET)", async () => {
43	    const res = await t.fetch("/test.png", {
44	      headers: {
45	        "if-none-match": "w/456",
46	        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
47	        "accept-encoding": "gzip, br",
48	      },
49	    });
50	
51	    expect(res.status).toEqual(200);
52	    expect(await res.text()).toBe("asset:/test.png.gz");
53	    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
54	    expect(res.headers.get("content-length")).toBe("18");
55	  });
56	
57	  it("Can serve asset (HEAD)", async () => {
58	    const headRes = await t.fetch("/test.png", {
59	      method: "HEAD",
60	      headers: {
61	        "if-none-match": "w/456",
62	        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
63	        "accept-encoding": "gzip, br",
64	      },
65	    });
66	
67	    expect(headRes.status).toEqual(200);
68	    expect(await headRes.text()).toBe("");
69	    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
70	    expect(headRes.headers.get("content-length")).toBe("18");
71	  });
72	
73	  it("Sets vary when a single encoding is accepted", async () => {
74	    const res = await t.fetch("/test.png", {
75	      headers: { "accept-encoding": "gzip" },
76	    });
77	    expect(await res.text()).toBe("asset:/test.png.gz");
78	    expect(res.headers.get("vary")).toBe("accept-encoding");
79	  });
80	
81	  it("Keeps existing vary values", async () => {
82	    t.app.all("/cors/**", (event) => {
83	      event.res.headers.set("vary", "origin");
84	      return serveStatic(event, {
85	        getContents: (id) => `asset:${id}`,
86	        getMeta: (id) => ({ type: "text/plain", path: id }),
87	        encodings: { gzip: ".gz" },
88	      });
89	    });
90	    const res = await t.fetch("/cors/test.png", {
91	      headers: { "accept-encoding": "gzip" },
92	    });
93	    expect(res.headers.get("vary")).toBe("origin, accept-encoding");
94	  });
95	
96	  it("Sets vary when no encoding is accepted", async () => {
97	    // Explicit `identity`: node's fetch adds `accept-encoding: gzip, deflate` when unset.
98	    const res = await t.fetch("/test.png", {
99	      headers: { "accept-encoding": "identity" },
100	    });
101	    expect(await res.text()).toBe("asset:/test.png");
102	    expect(res.headers.get("vary")).toBe("accept-encoding");
103	  });
104	
105	  it("Does not set vary without configured encodings", async () => {
106	    t.app.all("/plain/**", (event) => {
107	      return serveStatic(event, {
108	        getContents: (id) => `asset:${id}`,
109	        getMeta: (id) => ({ type: "text/plain", path: id }),
110	      });
111	    });
112	    const res = await t.fetch("/plain/test.png", {
113	      headers: { "accept-encoding": "gzip" },
114	    });
115	    expect(res.headers.get("vary")).toBeNull();
116	  });
117	
118	  it("Does not duplicate vary values", async () => {
119	    for (const [i, vary] of ["Accept-Encoding", "origin,accept-encoding", "*"].entries()) {
120	      t.app.all(`/dedupe${i}/**`, (event) => {
121	        event.res.headers.set("vary", vary);
122	        return serveStatic(event, {
123	          getContents: (id) => `asset:${id}`,
124	          getMeta: (id) => ({ type: "text/plain", path: id }),
125	          encodings: { gzip: ".gz" },
126	        });
127	      });
128	      const res = await t.fetch(`/dedupe${i}/test.png`, {
129	        headers: { "accept-encoding": "gzip" },
130	      });
131	      expect(res.headers.get("vary")).toBe(vary);
132	    }
133	  });
134	
135	  it("Matches encodings with q-values and any case", async () => {
136	    for (const [acceptEncoding, expected] of [
137	      ["gzip;q=1.0", "asset:/test.png.gz"],
138	      ["GZIP", "asset:/test.png.gz"],
139	      ["br ; q=1", "asset:/test.png.br"],
140	      // Preferred by weight, not by header order.
141	      ["gzip;q=0.5, br;q=0.8", "asset:/test.png.br"],
142	      // Equal weights keep header order.
143	      ["br, gzip", "asset:/test.png.br"],
144	      // `q=0` means "not acceptable".
145	      ["gzip;q=0, br;q=0.000", "asset:/test.png"],
146	      ["gzip;q=0", "asset:/test.png"],
